/**
 * CappenSplashReveal
 *
 * TRUST / CENTRIC / EXCHANGE hero ΓÇö cappen.com-style staggered layout.
 *
 * Hover reveal: a WebGL Navier-Stokes fluid simulation acts as an eraser
 * for a white cover layer via mix-blend-mode: destination-out.
 * Beneath the cover sits neon-green (#a3ff12) text that becomes visible
 * wherever the user's cursor drags fluid.
 *
 * Architecture (bottom ΓåÆ top):
 *   z-0 ΓÇö Neon green text (hidden by cover)
 *   z-10 ΓÇö Cover group (isolation: isolate):
 *          Γö£ΓöÇΓöÇ White bg + black text (what you see by default)
 *          ΓööΓöÇΓöÇ FluidCanvas (destination-out erases cover where fluid flows)
 */

import React, { useRef, useEffect } from "react";
import gsap from "gsap";
import FluidCanvas from "./FluidCanvas";

interface CappenSplashRevealProps {
  texts: string[];
}

export const CappenSplashReveal: React.FC<CappenSplashRevealProps> = ({ texts }) => {
  const containerRef = useRef<HTMLDivElement>(null);

  /* Black text line refs (cover layer ΓÇö GSAP entrance) */
  const line1Ref = useRef<HTMLSpanElement>(null);
  const line2Ref = useRef<HTMLSpanElement>(null);
  const line3Ref = useRef<HTMLDivElement>(null);

  /* Green text line refs (reveal layer ΓÇö animated in sync) */
  const greenLine1Ref = useRef<HTMLSpanElement>(null);
  const greenLine2Ref = useRef<HTMLSpanElement>(null);
  const greenLine3Ref = useRef<HTMLDivElement>(null);

  /* -- GSAP entrance: animate both layers' lines in perfect sync ------- */
  useEffect(() => {
    const ctx = gsap.context(() => {
      const pairs = [
        [line1Ref.current, greenLine1Ref.current],
        [line2Ref.current, greenLine2Ref.current],
        [line3Ref.current, greenLine3Ref.current],
      ];
      pairs.forEach((pair, i) => {
        gsap.fromTo(
          pair,
          { y: 100, opacity: 0 },
          { y: 0, opacity: 1, duration: 1.4, ease: "power4.out", delay: 0.2 + i * 0.18 }
        );
      });
    }, containerRef);
    return () => ctx.revert();
  }, []);

  /* -- Shared text classes --------------------------------------------- */
  const sz =
    "font-display font-black uppercase leading-[0.82] tracking-[-0.03em] whitespace-nowrap select-none";
  const textSize = "text-[16.5vw] md:text-[14vw] lg:text-[12.5vw]";

  const [t0, t1, t2] = [texts[0] ?? "TRUST", texts[1] ?? "CENTRIC", texts[2] ?? "EXCHANGE"];

  /* Split EXCHANGE into EX + CHANGE for the decorative box */
  const ex = t2.slice(0, 2);  /* "EX" */
  const change = t2.slice(2);     /* "CHANGE" */

  /* -- Layout renderer (identical for both layers for pixel-perfect alignment) -- */
  const renderLayout = (
    color: string,
    layer: "base" | "reveal",
    refs?: { l1: React.RefObject<HTMLSpanElement | null>; l2: React.RefObject<HTMLSpanElement | null>; l3: React.RefObject<HTMLDivElement | null> }
  ) => (
    <div
      className="w-full h-full flex flex-col justify-center px-[4vw] md:px-[5vw] lg:px-[6vw]"
      aria-hidden={layer === "reveal" ? "true" : undefined}
    >
      {/* Line 1: TRUST ΓÇö left-aligned */}
      <span
        ref={refs?.l1 ?? undefined}
        className={`${sz} ${textSize} block`}
        style={{ color, alignSelf: "flex-start" }}
      >
        {t0}
      </span>

      {/* Line 2: CENTRIC ΓÇö right-aligned (offset) */}
      <span
        ref={refs?.l2 ?? undefined}
        className={`${sz} ${textSize} block -mt-[1.5vw]`}
        style={{ color, alignSelf: "flex-end", marginRight: "2vw" }}
      >
        {t1}
      </span>

      {/* Line 3: EX [box] CHANGE ΓÇö left-aligned */}
      <div
        ref={refs?.l3 ?? undefined}
        className="flex items-center gap-[2.5vw] -mt-[1.5vw]"
        style={{ alignSelf: "flex-start" }}
      >
        <span className={`${sz} ${textSize}`} style={{ color }}>{ex}</span>

        {/* Decorative spinning box ΓÇö only in base (cover) layer */}
        {layer === "base" && (
          <div
            className="flex-shrink-0 rounded-xl overflow-hidden"
            style={{
              width: "clamp(60px, 9.5vw, 140px)",
              height: "clamp(40px, 6.5vw,  96px)",
              background: "#0a0a0a",
              boxShadow: "0 4px 32px rgba(0,0,0,0.22)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <div
              style={{
                width: "72%",
                height: "72%",
                borderRadius: "50%",
                border: "1px solid rgba(255,255,255,0.18)",
                animation: "spin 10s linear infinite",
                position: "relative",
                opacity: 0.7,
              }}
            >
              <div style={{ position: "absolute", inset: 0, borderRadius: "50%", border: "8px solid rgba(255,255,255,0.06)" }} />
              <div style={{ position: "absolute", top: "50%", left: 0, right: 0, height: 1, background: "rgba(255,255,255,0.18)", transform: "translateY(-50%)" }} />
              <div style={{ position: "absolute", left: "50%", top: 0, bottom: 0, width: 1, background: "rgba(255,255,255,0.18)", transform: "translateX(-50%)" }} />
            </div>
          </div>
        )}

        {/* Reveal-layer placeholder box (keeps spacing identical to base) */}
        {layer === "reveal" && (
          <div
            className="flex-shrink-0"
            style={{
              width: "clamp(60px, 9.5vw, 140px)",
              height: "clamp(40px, 6.5vw,  96px)",
            }}
          />
        )}

        <span className={`${sz} ${textSize}`} style={{ color }}>{change}</span>
      </div>
    </div>
  );

  return (
    <div
      ref={containerRef}
      className="relative w-full h-full bg-white overflow-hidden"
      style={{ cursor: "none" }}
    >
      {/* ΓöÇΓöÇ Layer 0: Neon green text ΓÇö hidden under the cover ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div className="absolute inset-0 z-0 pointer-events-none">
        {renderLayout("#a3ff12", "reveal", { l1: greenLine1Ref, l2: greenLine2Ref, l3: greenLine3Ref })}
      </div>

      {/* ΓöÇΓöÇ Layer 1: Cover group ΓÇö white bg + black text + fluid eraser ΓöÇ */}
      <div
        className="absolute inset-0 z-10"
        style={{ isolation: "isolate" }}
      >
        {/* Default visible content: white background + black text */}
        <div className="absolute inset-0 bg-white">
          {renderLayout("#0a0a0a", "base", { l1: line1Ref, l2: line2Ref, l3: line3Ref })}
        </div>

        {/* WebGL fluid canvas ΓÇö destination-out erases the cover where fluid flows */}
        <FluidCanvas
          containerRef={containerRef}
          className="absolute inset-0 pointer-events-none"
          style={{ mixBlendMode: "destination-out" as any }}
        />
      </div>
    </div>
  );
};

import { useState, useEffect, useRef, useCallback, memo, useMemo } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { useTheme } from 'next-themes';
import { Sun, Moon, LogOut } from 'lucide-react';
import { useQueryClient } from '@tanstack/react-query';
import { useAuth } from '@/contexts/AuthContext';
import { isNavigationLocked, lockNavigation, safeNavigate, unlockNavigation } from '@/lib/utils';
import { useScrollTriggerCleanup } from '@/hooks/useScrollTriggerCleanup';
import { toast } from '@/components/ui/use-toast';
import NotificationCenter from './NotificationCenter';

// ScrollTrigger registered in lib/gsap-init.ts

interface NavItem {
  label: string;
  path: string;
  number: string;
}

const navItems: NavItem[] = [
  { label: 'Home', path: '/home', number: '00' },
  { label: 'Academics', path: '/academics', number: '01' },
  { label: 'Accommodation', path: '/accommodation', number: '02' },
  { label: 'Essentials', path: '/essentials', number: '03' },
  { label: 'Resale', path: '/resale', number: '04' },
];

const ContextNav = memo(function ContextNav() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isDark, setIsDark] = useState(false);
  const { theme, setTheme } = useTheme();
  // Use ref for scroll progress to avoid re-rendering entire nav tree on scroll
  const scrollProgressRef = useRef(0);
  const progressBarRef = useRef<HTMLDivElement>(null);
  const sectionLabelRef = useRef<HTMLSpanElement>(null);
  const navRef = useRef<HTMLElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const location = useLocation();
  const navigate = useNavigate();
  const { isAuthenticated, user, logout } = useAuth();
  // UX-02: invalidate all cached queries on logout to prevent stale data leakage
  const queryClient = useQueryClient();

  // Admin-aware nav items ΓÇö adds Admin Panel entry for admin users
  const displayNavItems = useMemo(() => {
    const base: NavItem[] = [
      { label: 'Home', path: '/home', number: '00' },
      { label: 'Academics', path: '/academics', number: '01' },
      { label: 'Accommodation', path: '/accommodation', number: '02' },
      { label: 'Essentials', path: '/essentials', number: '03' },
      { label: 'Resale', path: '/resale', number: '04' },
    ];
    if (user?.role === 'admin') {
      base.push({ label: 'Admin', path: '/admin', number: '05' });
    }
    return base;
  }, [user?.role]);

  // Kill ScrollTriggers when leaving animated pages (runs on all routes)
  useScrollTriggerCleanup();

  const isAuthPage = ['/login', '/signup', '/verify'].includes(location.pathname);
  const isLandingPage = location.pathname === '/';
  const isHomepage = location.pathname === '/home';

  // Pages with dark backgrounds need light nav text immediately
  const darkBgPages = ['/resale', '/accommodation', '/essentials', '/academics'];
  const isDarkBgPage = darkBgPages.includes(location.pathname);

  // Track scroll position and update nav style
  useEffect(() => {
    let rafId: number | null = null;
    let ticking = false;

    const handleScroll = () => {
      if (ticking) return;
      ticking = true;
      rafId = requestAnimationFrame(() => {
        const scrollTop = window.scrollY;
        const docHeight = document.documentElement.scrollHeight - window.innerHeight;
        const progress = docHeight > 0 ? scrollTop / docHeight : 0;
        scrollProgressRef.current = progress;

        // Direct DOM writes ΓÇö no React re-render needed
        if (progressBarRef.current) {
          progressBarRef.current.style.width = `${progress * 100}%`;
        }
        if (sectionLabelRef.current) {
          sectionLabelRef.current.textContent =
            progress < 0.06 ? 'Welcome' : progress < 0.5 ? 'Explore' : 'Discover';
        }
        // Nav remains fully visible on homepage
        if (isHomepage && navRef.current) {
          navRef.current.style.opacity = '1';
        }

        // Only trigger React re-render for dark mode threshold crossing
        const shouldBeDark = isDarkBgPage ? true : progress > 0.06;
        setIsDark(prev => prev === shouldBeDark ? prev : shouldBeDark);
        ticking = false;
      });
    };

    // Set initial state for dark-bg pages
    if (isDarkBgPage) setIsDark(true);

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => {
      window.removeEventListener('scroll', handleScroll);
      if (rafId) cancelAnimationFrame(rafId);
    };
  }, [isDarkBgPage, isHomepage]);

  // Animate menu open/close with automatic lifecycle management
  useEffect(() => {
    if (!menuRef.current) return;

    const ctx = gsap.context(() => {
      if (isMenuOpen) {
        gsap.fromTo(
          menuRef.current!,
          { clipPath: 'circle(0% at calc(100% - 40px) 40px)' },
          { clipPath: 'circle(150% at calc(100% - 40px) 40px)', duration: 0.8, ease: 'power3.inOut' }
        );

        const menuNavItems = menuRef.current!.querySelectorAll('.nav-item');
        gsap.fromTo(
          menuNavItems,
          { opacity: 0, x: 100 },
          { opacity: 1, x: 0, stagger: 0.1, delay: 0.3, duration: 0.6, ease: 'power3.out' }
        );
      } else {
        gsap.to(menuRef.current!, {
          clipPath: 'circle(0% at calc(100% - 40px) 40px)',
          duration: 0.6,
          ease: 'power3.inOut',
        });
      }
    });

    return () => ctx.revert();
  }, [isMenuOpen]);

  // Guard against rapid navigation clicks during page transitions
  const handleNavClick = useCallback((e: React.MouseEvent<HTMLAnchorElement>, targetPath: string) => {
    // Block if already transitioning
    if (isNavigationLocked()) {
      e.preventDefault();
      return;
    }
    // Skip if navigating to current page
    if (location.pathname === targetPath) {
      e.preventDefault();
      return;
    }
    // Lock immediately to prevent race condition before PageTransition starts
    lockNavigation(2000);
    setIsMenuOpen(false);
  }, [location.pathname]);

  // Safe logout with navigation guard
  // UX-01: redirect to /login (not /) ΓÇö users expect the login screen after logout,
  // not the animated landing splash which looks like a crash.
  // UX-02: clear React Query cache to prevent stale private data on shared devices.
  const handleLogout = useCallback(() => {
    // Logout is terminal session teardown and must not be blocked by a stale
    // route-transition lock from an earlier navigation.
    unlockNavigation();
    setIsMenuOpen(false);
    queryClient.clear(); // UX-02: wipe all cached queries
    logout();
    toast({ title: 'Signed Out', description: 'You have been logged out successfully.' });
    navigate('/login', { replace: true });
  }, [logout, navigate, location.pathname, queryClient]);

  // ΓöÇΓöÇ Early return AFTER all hooks ΓöÇΓöÇ
  if (isAuthPage || isLandingPage) return null;

  // During the hero phase on homepage, the splash effect handles masking
  // The REAL nav stays fully interactive and visible.

  return (
    <>
      {/* Fixed Navigation Bar */}
      <nav
        ref={navRef}
        className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${isDark ? 'text-portal-foreground' : 'text-foreground'
          }`}
        style={{
          pointerEvents: 'auto',  // Γÿà Always clickable
          transition: 'opacity 0.4s ease, color 0.4s ease',
        }}
      >
        <div className="flex items-center justify-between px-6 md:px-12 py-6">
          {/* Logo */}
          <Link
            to="/home"
            onClick={(e) => handleNavClick(e, '/home')}
            className="relative z-50 font-display font-bold text-xl tracking-tight hover:opacity-70 transition-opacity"
          >
            <span className="sr-only">BErozgar</span>
            <div className="flex items-center gap-2">
              <div className={`w-8 h-8 border-2 ${isDark ? 'border-portal-foreground' : 'border-foreground'} rotate-45 flex items-center justify-center`}>
                <div className={`w-3 h-3 ${isDark ? 'bg-portal-foreground' : 'bg-foreground'}`} />
              </div>
              <span className="hidden md:block uppercase">BErozgar</span>
            </div>
          </Link>

          {/* Center - Current section indicator */}
          <div className="hidden md:flex items-center gap-4">
            <div className={`h-px w-12 ${isDark ? 'bg-portal-foreground/30' : 'bg-foreground/30'}`} />
            <span ref={sectionLabelRef} className="text-xs uppercase tracking-widest opacity-60 font-body">
              Welcome
            </span>
            <div className={`h-px w-12 ${isDark ? 'bg-portal-foreground/30' : 'bg-foreground/30'}`} />
          </div>

          {/* Nav Actions */}
          <div className="flex items-center gap-4 md:gap-6">
            {/* Auth Action */}
            {isAuthenticated ? (
              <Link
                to="/profile"
                onClick={(e) => handleNavClick(e, '/profile')}
                className="group relative flex items-center gap-3 cursor-pointer"
              >
                <div className="hidden lg:flex flex-col items-end">
                  <span className="text-[8px] uppercase tracking-[0.2em] opacity-40 font-mono">
                    Identity
                  </span>
                  <span className="text-[10px] font-bold uppercase tracking-widest">
                    {user?.fullName?.split(' ')[0] || 'Profile'}
                  </span>
                </div>
                <div className={`relative w-8 h-8 rounded-full border border-current flex items-center justify-center overflow-hidden transition-all duration-300 group-hover:scale-110 group-hover:border-[#a3ff12] ${isDark ? 'border-portal-foreground' : 'border-foreground'}`}>
                  <div className={`w-5 h-5 rounded-full flex items-center justify-center font-bold text-[10px] ${isDark ? 'bg-portal-foreground text-portal' : 'bg-black text-white'}`}>
                    {user?.fullName?.[0] || 'U'}
                  </div>
                </div>
              </Link>
            ) : (
              <Link
                to="/login"
                onClick={(e) => handleNavClick(e, '/login')}
                className={`text-[10px] uppercase tracking-widest opacity-60 hover:opacity-100 transition-opacity font-body ${isDark ? 'text-portal-foreground' : 'text-foreground'}`}
              >
                Login
              </Link>
            )}

            <button
              onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
              className={`p-2 transition-all duration-300 opacity-60 hover:opacity-100 ${isDark ? 'text-portal-foreground' : 'text-foreground'}`}
              aria-label="Toggle structural mode"
            >
              {theme === 'dark' ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
            </button>

            {isAuthenticated && (
              <button
                onClick={handleLogout}
                className={`p-2 transition-all duration-300 opacity-60 hover:opacity-100 ${isDark ? 'text-portal-foreground' : 'text-foreground'}`}
                aria-label="Logout"
              >
                <LogOut className="w-5 h-5" />
              </button>
            )}

            <NotificationCenter isDark={isDark} />

            {/* Menu Button */}
            <button
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className="relative z-50 flex items-center gap-3 group"
              aria-label="Toggle menu"
            >
              <span className={`text-xs uppercase tracking-widest transition-opacity ${isMenuOpen ? 'opacity-0' : 'opacity-60'} font-body`}>
                Menu
              </span>
              <div className="relative w-8 h-8 flex items-center justify-center">
                <span
                  className={`absolute block w-6 h-0.5 transition-all duration-300 ${isDark || isMenuOpen ? 'bg-portal-foreground' : 'bg-foreground'
                    } ${isMenuOpen ? 'rotate-45' : '-translate-y-1.5'}`}
                />
                <span
                  className={`absolute block w-6 h-0.5 transition-all duration-300 ${isDark || isMenuOpen ? 'bg-portal-foreground' : 'bg-foreground'
                    } ${isMenuOpen ? '-rotate-45' : 'translate-y-1.5'}`}
                />
              </div>
            </button>
          </div>

          {/* Progress bar */}
          <div className={`absolute bottom-0 left-0 h-px ${isDark ? 'bg-portal-foreground/20' : 'bg-foreground/20'} w-full`}>
            <div
              ref={progressBarRef}
              className={`h-full ${isDark ? 'bg-portal-foreground' : 'bg-foreground'} transition-all duration-100`}
              style={{ width: '0%' }}
            />
          </div>
        </div>
      </nav>

      {/* Fullscreen Menu Overlay */}
      <div
        ref={menuRef}
        className="fixed inset-0 z-40 bg-portal flex items-center justify-center"
        style={{ clipPath: 'circle(0% at calc(100% - 40px) 40px)', willChange: 'clip-path' }}
        role="dialog"
        aria-modal={isMenuOpen}
        aria-label="Navigation menu"
      >
        <div className="max-w-4xl w-full px-8 md:px-16">
          <nav className="space-y-4 md:space-y-6">
            {displayNavItems.map((item) => (
              <Link
                key={item.path}
                to={item.path}
                onClick={(e) => handleNavClick(e, item.path)}
                aria-current={location.pathname === item.path ? 'page' : undefined}
                className={`nav-item block group ${location.pathname === item.path ? 'opacity-100' : 'opacity-60 hover:opacity-100'
                  }`}
              >
                <div className="flex items-baseline gap-4 md:gap-8">
                  <span className="text-portal-foreground/40 text-sm font-body">{item.number}</span>
                  <span className="text-portal-foreground font-display text-4xl md:text-7xl font-bold uppercase tracking-tight group-hover:tracking-wide transition-[color,letter-spacing] duration-300">
                    {item.label}
                  </span>
                </div>
                <div className="ml-8 md:ml-16 mt-1 h-px bg-portal-foreground/20 origin-left scale-x-0 group-hover:scale-x-100 transition-transform duration-500" />
              </Link>
            ))}
          </nav>

          {/* Menu footer */}
          <div className="mt-16 md:mt-24 flex flex-col md:flex-row justify-between items-start md:items-end gap-8">
            <div>
              <p className="text-portal-foreground/40 text-xs uppercase tracking-widest mb-2">Institution</p>
              <p className="text-portal-foreground font-display text-lg">MCTRGIT</p>
            </div>
            <div>
              <p className="text-portal-foreground/40 text-xs uppercase tracking-widest mb-2">Platform</p>
              <p className="text-portal-foreground font-display text-lg">Trust-Centric Exchange</p>
            </div>
            <div>
              <p className="text-portal-foreground/40 text-xs uppercase tracking-widest mb-2">Access</p>
              {isAuthenticated ? (
                <div className="flex items-center gap-4">
                  <p className="text-portal-foreground font-display text-lg capitalize">{user?.role || 'Student'}</p>
                  {user?.role === 'admin' && (
                    <Link
                      to="/admin"
                      onClick={(e) => handleNavClick(e, '/admin')}
                      className="text-[#a3ff12] text-xs uppercase tracking-widest hover:opacity-80 transition-opacity"
                    >
                      Admin Panel ΓåÆ
                    </Link>
                  )}
                </div>
              ) : (
                <Link
                  to="/login"
                  onClick={(e) => handleNavClick(e, '/login')}
                  className="text-portal-foreground font-display text-lg hover:text-[#a3ff12] transition-colors"
                >
                  Sign In ΓåÆ
                </Link>
              )}
            </div>
          </div>
        </div>
      </div>
    </>
  );
});

export default ContextNav;

/**
 * FluidCanvas ΓÇö WebGL fluid simulation canvas for hover-based reveals.
 *
 * Renders a Navier-Stokes fluid simulation that responds to mouse/touch
 * movement. The canvas output is transparent with colored fluid blobs,
 * designed to be used with mix-blend-mode: destination-out to punch holes
 * through a cover layer.
 *
 * Adapted for container-scoped events (not window-global).
 */

import { useEffect, useRef } from 'react';

interface FluidCanvasProps {
  /** Parent container ref ΓÇö events are scoped to this element */
  containerRef: React.RefObject<HTMLElement | null>;
  className?: string;
  style?: React.CSSProperties;
}

export default function FluidCanvas({ containerRef, className = '', style }: FluidCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameId = useRef<number | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    let isActive = true;

    // ΓöÇΓöÇ Pointer prototype ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    function pointerPrototype(this: any) {
      this.id = -1;
      this.texcoordX = 0;
      this.texcoordY = 0;
      this.prevTexcoordX = 0;
      this.prevTexcoordY = 0;
      this.deltaX = 0;
      this.deltaY = 0;
      this.down = false;
      this.moved = false;
      this.color = [0, 0, 0];
    }

    const config = {
      SIM_RESOLUTION: 64,
      DYE_RESOLUTION: 512,
      DENSITY_DISSIPATION: 0.985,
      VELOCITY_DISSIPATION: 0.97,
      PRESSURE: 0.8,
      PRESSURE_ITERATIONS: 20,
      CURL: 3,
      SPLAT_RADIUS: 0.4,
      SPLAT_FORCE: 6000,
      SHADING: false,
      COLOR_UPDATE_SPEED: 10,
      PAUSED: false,
      BACK_COLOR: { r: 0, g: 0, b: 0 },
      TRANSPARENT: true,
    };

    // ΓöÇΓöÇ Smoothed pointer with easing/delay ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const smoothPointer = {
      x: 0, y: 0,          // smoothed position (in canvas-scaled pixels)
      targetX: 0, targetY: 0, // raw mouse position
      active: false,         // is the mouse inside the container?
    };
    const SMOOTH_FACTOR = 0.08; // lower = more delay/smoothness (cappen-like buttery follow)

    const pointers = [new (pointerPrototype as any)()];

    // ΓöÇΓöÇ WebGL context ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const params: WebGLContextAttributes = {
      alpha: true,
      depth: false,
      stencil: false,
      antialias: false,
      preserveDrawingBuffer: false,
    };

    let gl: any = canvas.getContext('webgl2', params);
    const isWebGL2 = !!gl;
    if (!isWebGL2) gl = canvas.getContext('webgl', params) || canvas.getContext('experimental-webgl', params);
    if (!gl) return;

    let halfFloat: any;
    let supportLinearFiltering: any;
    if (isWebGL2) {
      gl.getExtension('EXT_color_buffer_float');
      supportLinearFiltering = gl.getExtension('OES_texture_float_linear');
    } else {
      halfFloat = gl.getExtension('OES_texture_half_float');
      supportLinearFiltering = gl.getExtension('OES_texture_half_float_linear');
    }

    gl.clearColor(0.0, 0.0, 0.0, 1.0);

    const halfFloatTexType = isWebGL2 ? gl.HALF_FLOAT : halfFloat?.HALF_FLOAT_OES;

    function getSupportedFormat(gl: any, internalFormat: number, format: number, type: number): any {
      if (!supportRenderTextureFormat(gl, internalFormat, format, type)) {
        switch (internalFormat) {
          case gl.R16F: return getSupportedFormat(gl, gl.RG16F, gl.RG, type);
          case gl.RG16F: return getSupportedFormat(gl, gl.RGBA16F, gl.RGBA, type);
          default: return null;
        }
      }
      return { internalFormat, format };
    }

    function supportRenderTextureFormat(gl: any, internalFormat: number, format: number, type: number): boolean {
      const texture = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, texture);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.texImage2D(gl.TEXTURE_2D, 0, internalFormat, 4, 4, 0, format, type, null);
      const fbo = gl.createFramebuffer();
      gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, texture, 0);
      return gl.checkFramebufferStatus(gl.FRAMEBUFFER) === gl.FRAMEBUFFER_COMPLETE;
    }

    let formatRGBA: any, formatRG: any, formatR: any;
    if (isWebGL2) {
      formatRGBA = getSupportedFormat(gl, gl.RGBA16F, gl.RGBA, halfFloatTexType);
      formatRG = getSupportedFormat(gl, gl.RG16F, gl.RG, halfFloatTexType);
      formatR = getSupportedFormat(gl, gl.R16F, gl.RED, halfFloatTexType);
    } else {
      formatRGBA = getSupportedFormat(gl, gl.RGBA, gl.RGBA, halfFloatTexType);
      formatRG = getSupportedFormat(gl, gl.RGBA, gl.RGBA, halfFloatTexType);
      formatR = getSupportedFormat(gl, gl.RGBA, gl.RGBA, halfFloatTexType);
    }

    if (!formatRGBA || !formatRG || !formatR) return;

    if (!supportLinearFiltering) {
      config.DYE_RESOLUTION = 256;
      config.SHADING = false;
    }

    // ΓöÇΓöÇ Shader helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    function compileShader(type: number, source: string, keywords?: string[] | null): WebGLShader {
      if (keywords) {
        source = keywords.map((k: string) => '#define ' + k + '\n').join('') + source;
      }
      const shader = gl.createShader(type)!;
      gl.shaderSource(shader, source);
      gl.compileShader(shader);
      if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
        console.warn('[FluidCanvas shader]', gl.getShaderInfoLog(shader));
      }
      return shader;
    }

    function createProgram(vs: WebGLShader, fs: WebGLShader): WebGLProgram {
      const p = gl.createProgram()!;
      gl.attachShader(p, vs);
      gl.attachShader(p, fs);
      gl.linkProgram(p);
      if (!gl.getProgramParameter(p, gl.LINK_STATUS)) {
        console.warn('[FluidCanvas program]', gl.getProgramInfoLog(p));
      }
      return p;
    }

    function getUniforms(program: WebGLProgram): Record<string, WebGLUniformLocation> {
      const uniforms: Record<string, WebGLUniformLocation> = {};
      const count = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
      for (let i = 0; i < count; i++) {
        const name = gl.getActiveUniform(program, i)!.name;
        uniforms[name] = gl.getUniformLocation(program, name)!;
      }
      return uniforms;
    }

    class Program {
      uniforms: Record<string, WebGLUniformLocation>;
      program: WebGLProgram;
      constructor(vs: WebGLShader, fs: WebGLShader) {
        this.program = createProgram(vs, fs);
        this.uniforms = getUniforms(this.program);
      }
      bind() { gl.useProgram(this.program); }
    }

    class Material {
      vertexShader: WebGLShader;
      fragmentShaderSource: string;
      programs: Record<number, WebGLProgram> = {};
      activeProgram: WebGLProgram | null = null;
      uniforms: Record<string, WebGLUniformLocation> = {};
      constructor(vs: WebGLShader, fsSrc: string) {
        this.vertexShader = vs;
        this.fragmentShaderSource = fsSrc;
      }
      setKeywords(keywords: string[]) {
        let hash = 0;
        for (const k of keywords) {
          let h = 0;
          for (let i = 0; i < k.length; i++) h = (h << 5) - h + k.charCodeAt(i) | 0;
          hash += h;
        }
        let program = this.programs[hash];
        if (!program) {
          const fs = compileShader(gl.FRAGMENT_SHADER, this.fragmentShaderSource, keywords);
          program = createProgram(this.vertexShader, fs);
          this.programs[hash] = program;
        }
        if (program === this.activeProgram) return;
        this.uniforms = getUniforms(program);
        this.activeProgram = program;
      }
      bind() { gl.useProgram(this.activeProgram); }
    }

    // ΓöÇΓöÇ Shaders ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const baseVS = compileShader(gl.VERTEX_SHADER, `
      precision highp float;
      attribute vec2 aPosition;
      varying vec2 vUv;
      varying vec2 vL; varying vec2 vR; varying vec2 vT; varying vec2 vB;
      uniform vec2 texelSize;
      void main () {
        vUv = aPosition * 0.5 + 0.5;
        vL = vUv - vec2(texelSize.x, 0.0);
        vR = vUv + vec2(texelSize.x, 0.0);
        vT = vUv + vec2(0.0, texelSize.y);
        vB = vUv - vec2(0.0, texelSize.y);
        gl_Position = vec4(aPosition, 0.0, 1.0);
      }
    `);

    const copyFS = compileShader(gl.FRAGMENT_SHADER, `
      precision mediump float;
      precision mediump sampler2D;
      varying highp vec2 vUv;
      uniform sampler2D uTexture;
      void main () { gl_FragColor = texture2D(uTexture, vUv); }
    `);

    const clearFS = compileShader(gl.FRAGMENT_SHADER, `
      precision mediump float;
      precision mediump sampler2D;
      varying highp vec2 vUv;
      uniform sampler2D uTexture;
      uniform float value;
      void main () { gl_FragColor = value * texture2D(uTexture, vUv); }
    `);

    const displayShaderSrc = `
      precision highp float;
      precision highp sampler2D;
      varying vec2 vUv;
      varying vec2 vL; varying vec2 vR; varying vec2 vT; varying vec2 vB;
      uniform sampler2D uTexture;
      uniform vec2 texelSize;
      void main () {
        vec3 c = texture2D(uTexture, vUv).rgb;
        float a = max(c.r, max(c.g, c.b));
        gl_FragColor = vec4(c, a);
      }
    `;

    const splatFS = compileShader(gl.FRAGMENT_SHADER, `
      precision highp float;
      precision highp sampler2D;
      varying vec2 vUv;
      uniform sampler2D uTarget;
      uniform float aspectRatio;
      uniform vec3 color;
      uniform vec2 point;
      uniform float radius;
      void main () {
        vec2 p = vUv - point.xy;
        p.x *= aspectRatio;
        vec3 splat = exp(-dot(p, p) / radius) * color;
        vec3 base = texture2D(uTarget, vUv).xyz;
        gl_FragColor = vec4(base + splat, 1.0);
      }
    `);

    const advectionFS = compileShader(gl.FRAGMENT_SHADER, `
      precision highp float;
      precision highp sampler2D;
      varying vec2 vUv;
      uniform sampler2D uVelocity;
      uniform sampler2D uSource;
      uniform vec2 texelSize;
      uniform vec2 dyeTexelSize;
      uniform float dt;
      uniform float dissipation;
      vec4 bilerp (sampler2D sam, vec2 uv, vec2 tsize) {
        vec2 st = uv / tsize - 0.5;
        vec2 iuv = floor(st);
        vec2 fuv = fract(st);
        vec4 a = texture2D(sam, (iuv + vec2(0.5, 0.5)) * tsize);
        vec4 b = texture2D(sam, (iuv + vec2(1.5, 0.5)) * tsize);
        vec4 c = texture2D(sam, (iuv + vec2(0.5, 1.5)) * tsize);
        vec4 d = texture2D(sam, (iuv + vec2(1.5, 1.5)) * tsize);
        return mix(mix(a, b, fuv.x), mix(c, d, fuv.x), fuv.y);
      }
      void main () {
        #ifdef MANUAL_FILTERING
          vec2 coord = vUv - dt * bilerp(uVelocity, vUv, texelSize).xy * texelSize;
          vec4 result = bilerp(uSource, coord, dyeTexelSize);
        #else
          vec2 coord = vUv - dt * texture2D(uVelocity, vUv).xy * texelSize;
          vec4 result = texture2D(uSource, coord);
        #endif
        float decay = 1.0 + dissipation * dt;
        gl_FragColor = result / decay;
      }
    `, supportLinearFiltering ? null : ['MANUAL_FILTERING']);

    const divergenceFS = compileShader(gl.FRAGMENT_SHADER, `
      precision mediump float;
      precision mediump sampler2D;
      varying highp vec2 vUv;
      varying highp vec2 vL; varying highp vec2 vR;
      varying highp vec2 vT; varying highp vec2 vB;
      uniform sampler2D uVelocity;
      void main () {
        float L = texture2D(uVelocity, vL).x;
        float R = texture2D(uVelocity, vR).x;
        float T = texture2D(uVelocity, vT).y;
        float B = texture2D(uVelocity, vB).y;
        vec2 C = texture2D(uVelocity, vUv).xy;
        if (vL.x < 0.0) L = -C.x;
        if (vR.x > 1.0) R = -C.x;
        if (vT.y > 1.0) T = -C.y;
        if (vB.y < 0.0) B = -C.y;
        float div = 0.5 * (R - L + T - B);
        gl_FragColor = vec4(div, 0.0, 0.0, 1.0);
      }
    `);

    const curlFS = compileShader(gl.FRAGMENT_SHADER, `
      precision mediump float;
      precision mediump sampler2D;
      varying highp vec2 vUv;
      varying highp vec2 vL; varying highp vec2 vR;
      varying highp vec2 vT; varying highp vec2 vB;
      uniform sampler2D uVelocity;
      void main () {
        float L = texture2D(uVelocity, vL).y;
        float R = texture2D(uVelocity, vR).y;
        float T = texture2D(uVelocity, vT).x;
        float B = texture2D(uVelocity, vB).x;
        float vorticity = R - L - T + B;
        gl_FragColor = vec4(0.5 * vorticity, 0.0, 0.0, 1.0);
      }
    `);

    const vorticityFS = compileShader(gl.FRAGMENT_SHADER, `
      precision highp float;
      precision highp sampler2D;
      varying vec2 vUv;
      varying vec2 vL; varying vec2 vR; varying vec2 vT; varying vec2 vB;
      uniform sampler2D uVelocity;
      uniform sampler2D uCurl;
      uniform float curl;
      uniform float dt;
      void main () {
        float L = texture2D(uCurl, vL).x;
        float R = texture2D(uCurl, vR).x;
        float T = texture2D(uCurl, vT).x;
        float B = texture2D(uCurl, vB).x;
        float C = texture2D(uCurl, vUv).x;
        vec2 force = 0.5 * vec2(abs(T) - abs(B), abs(R) - abs(L));
        force /= length(force) + 0.0001;
        force *= curl * C;
        force.y *= -1.0;
        vec2 velocity = texture2D(uVelocity, vUv).xy;
        velocity += force * dt;
        velocity = min(max(velocity, -1000.0), 1000.0);
        gl_FragColor = vec4(velocity, 0.0, 1.0);
      }
    `);

    const pressureFS = compileShader(gl.FRAGMENT_SHADER, `
      precision mediump float;
      precision mediump sampler2D;
      varying highp vec2 vUv;
      varying highp vec2 vL; varying highp vec2 vR;
      varying highp vec2 vT; varying highp vec2 vB;
      uniform sampler2D uPressure;
      uniform sampler2D uDivergence;
      void main () {
        float L = texture2D(uPressure, vL).x;
        float R = texture2D(uPressure, vR).x;
        float T = texture2D(uPressure, vT).x;
        float B = texture2D(uPressure, vB).x;
        float divergence = texture2D(uDivergence, vUv).x;
        float pressure = (L + R + B + T - divergence) * 0.25;
        gl_FragColor = vec4(pressure, 0.0, 0.0, 1.0);
      }
    `);

    const gradientSubtractFS = compileShader(gl.FRAGMENT_SHADER, `
      precision mediump float;
      precision mediump sampler2D;
      varying highp vec2 vUv;
      varying highp vec2 vL; varying highp vec2 vR;
      varying highp vec2 vT; varying highp vec2 vB;
      uniform sampler2D uPressure;
      uniform sampler2D uVelocity;
      void main () {
        float L = texture2D(uPressure, vL).x;
        float R = texture2D(uPressure, vR).x;
        float T = texture2D(uPressure, vT).x;
        float B = texture2D(uPressure, vB).x;
        vec2 velocity = texture2D(uVelocity, vUv).xy;
        velocity.xy -= vec2(R - L, T - B);
        gl_FragColor = vec4(velocity, 0.0, 1.0);
      }
    `);

    // ΓöÇΓöÇ Blit quad ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, -1, 1, 1, 1, 1, -1]), gl.STATIC_DRAW);
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, gl.createBuffer());
    gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint16Array([0, 1, 2, 0, 2, 3]), gl.STATIC_DRAW);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
    gl.enableVertexAttribArray(0);

    function blit(target: any, clear = false) {
      if (target == null) {
        gl.viewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight);
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      } else {
        gl.viewport(0, 0, target.width, target.height);
        gl.bindFramebuffer(gl.FRAMEBUFFER, target.fbo);
      }
      if (clear) {
        gl.clearColor(0.0, 0.0, 0.0, 1.0);
        gl.clear(gl.COLOR_BUFFER_BIT);
      }
      gl.drawElements(gl.TRIANGLES, 6, gl.UNSIGNED_SHORT, 0);
    }

    // ΓöÇΓöÇ FBO helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    let dye: any, velocity: any, divergence: any, curl: any, pressure: any;

    const copyProgram = new Program(baseVS, copyFS);
    const clearProgram = new Program(baseVS, clearFS);
    const splatProgram = new Program(baseVS, splatFS);
    const advectionProgram = new Program(baseVS, advectionFS);
    const divergenceProgram = new Program(baseVS, divergenceFS);
    const curlProgram = new Program(baseVS, curlFS);
    const vorticityProgram = new Program(baseVS, vorticityFS);
    const pressureProgram = new Program(baseVS, pressureFS);
    const gradientSubtractProgram = new Program(baseVS, gradientSubtractFS);
    const displayMaterial = new Material(baseVS, displayShaderSrc);

    function getResolution(resolution: number) {
      let aspectRatio = gl.drawingBufferWidth / gl.drawingBufferHeight;
      if (aspectRatio < 1) aspectRatio = 1.0 / aspectRatio;
      const min = Math.round(resolution);
      const max = Math.round(resolution * aspectRatio);
      if (gl.drawingBufferWidth > gl.drawingBufferHeight) return { width: max, height: min };
      return { width: min, height: max };
    }

    function createFBO(w: number, h: number, iF: number, f: number, t: number, param: number) {
      gl.activeTexture(gl.TEXTURE0);
      const texture = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, texture);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, param);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, param);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.texImage2D(gl.TEXTURE_2D, 0, iF, w, h, 0, f, t, null);
      const fbo = gl.createFramebuffer();
      gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, texture, 0);
      gl.viewport(0, 0, w, h);
      gl.clear(gl.COLOR_BUFFER_BIT);
      return {
        texture, fbo, width: w, height: h,
        texelSizeX: 1.0 / w, texelSizeY: 1.0 / h,
        attach(id: number) { gl.activeTexture(gl.TEXTURE0 + id); gl.bindTexture(gl.TEXTURE_2D, texture); return id; },
      };
    }

    function createDoubleFBO(w: number, h: number, iF: number, f: number, t: number, param: number) {
      let fbo1 = createFBO(w, h, iF, f, t, param);
      let fbo2 = createFBO(w, h, iF, f, t, param);
      return {
        width: w, height: h, texelSizeX: fbo1.texelSizeX, texelSizeY: fbo1.texelSizeY,
        get read() { return fbo1; }, set read(v) { fbo1 = v; },
        get write() { return fbo2; }, set write(v) { fbo2 = v; },
        swap() { const t = fbo1; fbo1 = fbo2; fbo2 = t; },
      };
    }

    function resizeFBO(target: any, w: number, h: number, iF: number, f: number, t: number, param: number) {
      const newFBO = createFBO(w, h, iF, f, t, param);
      copyProgram.bind();
      gl.uniform1i(copyProgram.uniforms.uTexture, target.attach(0));
      blit(newFBO);
      return newFBO;
    }

    function resizeDoubleFBO(target: any, w: number, h: number, iF: number, f: number, t: number, param: number) {
      if (target.width === w && target.height === h) return target;
      target.read = resizeFBO(target.read, w, h, iF, f, t, param);
      target.write = createFBO(w, h, iF, f, t, param);
      target.width = w; target.height = h;
      target.texelSizeX = 1.0 / w; target.texelSizeY = 1.0 / h;
      return target;
    }

    function initFramebuffers() {
      const simRes = getResolution(config.SIM_RESOLUTION);
      const dyeRes = getResolution(config.DYE_RESOLUTION);
      const texType = halfFloatTexType;
      const filtering = supportLinearFiltering ? gl.LINEAR : gl.NEAREST;
      gl.disable(gl.BLEND);

      if (!dye) dye = createDoubleFBO(dyeRes.width, dyeRes.height, formatRGBA.internalFormat, formatRGBA.format, texType, filtering);
      else dye = resizeDoubleFBO(dye, dyeRes.width, dyeRes.height, formatRGBA.internalFormat, formatRGBA.format, texType, filtering);

      if (!velocity) velocity = createDoubleFBO(simRes.width, simRes.height, formatRG.internalFormat, formatRG.format, texType, filtering);
      else velocity = resizeDoubleFBO(velocity, simRes.width, simRes.height, formatRG.internalFormat, formatRG.format, texType, filtering);

      divergence = createFBO(simRes.width, simRes.height, formatR.internalFormat, formatR.format, texType, gl.NEAREST);
      curl = createFBO(simRes.width, simRes.height, formatR.internalFormat, formatR.format, texType, gl.NEAREST);
      pressure = createDoubleFBO(simRes.width, simRes.height, formatR.internalFormat, formatR.format, texType, gl.NEAREST);
    }

    function updateKeywords() {
      const keywords: string[] = [];
      if (config.SHADING) keywords.push('SHADING');
      displayMaterial.setKeywords(keywords);
    }

    updateKeywords();
    initFramebuffers();

    let lastUpdateTime = Date.now();
    let colorUpdateTimer = 0.0;

    // ΓöÇΓöÇ Color generation ΓÇö high values to saturate dye above 1.0 ΓöÇΓöÇ
    function generateColor() {
      // Values > 1.0 ensure the gaussian splat saturates well past 1.0
      // even at the edges. GL clamps output alpha to 1.0, so only the
      // very outermost fringe has partial alpha ΓÇö giving a clean solid
      // reveal with soft organic edges (cappen.com style).
      return { r: 3.0, g: 3.0, b: 3.0 };
    }

    function HSVtoRGB(h: number, s: number, v: number) {
      let r = 0, g = 0, b = 0;
      const i = Math.floor(h * 6);
      const f = h * 6 - i;
      const p = v * (1 - s);
      const q = v * (1 - f * s);
      const t = v * (1 - (1 - f) * s);
      switch (i % 6) {
        case 0: r = v; g = t; b = p; break;
        case 1: r = q; g = v; b = p; break;
        case 2: r = p; g = v; b = t; break;
        case 3: r = p; g = q; b = v; break;
        case 4: r = t; g = p; b = v; break;
        case 5: r = v; g = p; b = q; break;
      }
      return { r, g, b };
    }

    function scaleByPixelRatio(input: number) {
      return Math.floor(input * (window.devicePixelRatio || 1));
    }

    function correctRadius(radius: number) {
      const ar = canvas.width / canvas.height;
      if (ar > 1) radius *= ar;
      return radius;
    }

    function correctDeltaX(delta: number) {
      const ar = canvas.width / canvas.height;
      if (ar < 1) delta *= ar;
      return delta;
    }

    function correctDeltaY(delta: number) {
      const ar = canvas.width / canvas.height;
      if (ar > 1) delta /= ar;
      return delta;
    }

    function wrap(value: number, min: number, max: number) {
      const range = max - min;
      if (range === 0) return min;
      return ((value - min) % range) + min;
    }

    // ΓöÇΓöÇ Splat ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    function splat(x: number, y: number, dx: number, dy: number, color: any) {
      splatProgram.bind();
      gl.uniform1i(splatProgram.uniforms.uTarget, velocity.read.attach(0));
      gl.uniform1f(splatProgram.uniforms.aspectRatio, canvas.width / canvas.height);
      gl.uniform2f(splatProgram.uniforms.point, x, y);
      gl.uniform3f(splatProgram.uniforms.color, dx, dy, 0.0);
      gl.uniform1f(splatProgram.uniforms.radius, correctRadius(config.SPLAT_RADIUS / 100.0));
      blit(velocity.write);
      velocity.swap();

      gl.uniform1i(splatProgram.uniforms.uTarget, dye.read.attach(0));
      gl.uniform3f(splatProgram.uniforms.color, color.r, color.g, color.b);
      blit(dye.write);
      dye.swap();
    }

    function splatPointer(pointer: any) {
      const dx = pointer.deltaX * config.SPLAT_FORCE;
      const dy = pointer.deltaY * config.SPLAT_FORCE;
      splat(pointer.texcoordX, pointer.texcoordY, dx, dy, pointer.color);
    }

    // ΓöÇΓöÇ Simulation step ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    function step(dt: number) {
      gl.disable(gl.BLEND);

      curlProgram.bind();
      gl.uniform2f(curlProgram.uniforms.texelSize, velocity.texelSizeX, velocity.texelSizeY);
      gl.uniform1i(curlProgram.uniforms.uVelocity, velocity.read.attach(0));
      blit(curl);

      vorticityProgram.bind();
      gl.uniform2f(vorticityProgram.uniforms.texelSize, velocity.texelSizeX, velocity.texelSizeY);
      gl.uniform1i(vorticityProgram.uniforms.uVelocity, velocity.read.attach(0));
      gl.uniform1i(vorticityProgram.uniforms.uCurl, curl.attach(1));
      gl.uniform1f(vorticityProgram.uniforms.curl, config.CURL);
      gl.uniform1f(vorticityProgram.uniforms.dt, dt);
      blit(velocity.write);
      velocity.swap();

      divergenceProgram.bind();
      gl.uniform2f(divergenceProgram.uniforms.texelSize, velocity.texelSizeX, velocity.texelSizeY);
      gl.uniform1i(divergenceProgram.uniforms.uVelocity, velocity.read.attach(0));
      blit(divergence);

      clearProgram.bind();
      gl.uniform1i(clearProgram.uniforms.uTexture, pressure.read.attach(0));
      gl.uniform1f(clearProgram.uniforms.value, config.PRESSURE);
      blit(pressure.write);
      pressure.swap();

      pressureProgram.bind();
      gl.uniform2f(pressureProgram.uniforms.texelSize, velocity.texelSizeX, velocity.texelSizeY);
      gl.uniform1i(pressureProgram.uniforms.uDivergence, divergence.attach(0));
      for (let i = 0; i < config.PRESSURE_ITERATIONS; i++) {
        gl.uniform1i(pressureProgram.uniforms.uPressure, pressure.read.attach(1));
        blit(pressure.write);
        pressure.swap();
      }

      gradientSubtractProgram.bind();
      gl.uniform2f(gradientSubtractProgram.uniforms.texelSize, velocity.texelSizeX, velocity.texelSizeY);
      gl.uniform1i(gradientSubtractProgram.uniforms.uPressure, pressure.read.attach(0));
      gl.uniform1i(gradientSubtractProgram.uniforms.uVelocity, velocity.read.attach(1));
      blit(velocity.write);
      velocity.swap();

      advectionProgram.bind();
      gl.uniform2f(advectionProgram.uniforms.texelSize, velocity.texelSizeX, velocity.texelSizeY);
      if (!supportLinearFiltering)
        gl.uniform2f(advectionProgram.uniforms.dyeTexelSize, velocity.texelSizeX, velocity.texelSizeY);
      const velocityId = velocity.read.attach(0);
      gl.uniform1i(advectionProgram.uniforms.uVelocity, velocityId);
      gl.uniform1i(advectionProgram.uniforms.uSource, velocityId);
      gl.uniform1f(advectionProgram.uniforms.dt, dt);
      gl.uniform1f(advectionProgram.uniforms.dissipation, config.VELOCITY_DISSIPATION);
      blit(velocity.write);
      velocity.swap();

      if (!supportLinearFiltering)
        gl.uniform2f(advectionProgram.uniforms.dyeTexelSize, dye.texelSizeX, dye.texelSizeY);
      gl.uniform1i(advectionProgram.uniforms.uVelocity, velocity.read.attach(0));
      gl.uniform1i(advectionProgram.uniforms.uSource, dye.read.attach(1));
      gl.uniform1f(advectionProgram.uniforms.dissipation, config.DENSITY_DISSIPATION);
      blit(dye.write);
      dye.swap();
    }

    function render(target: any) {
      gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
      gl.enable(gl.BLEND);
      displayMaterial.bind();
      gl.uniform1i(displayMaterial.uniforms.uTexture, dye.read.attach(0));
      blit(target);
    }

    // ΓöÇΓöÇ Pointer tracking ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    function updatePointerMoveData(pointer: any, posX: number, posY: number, color: any) {
      pointer.prevTexcoordX = pointer.texcoordX;
      pointer.prevTexcoordY = pointer.texcoordY;
      pointer.texcoordX = posX / canvas.width;
      pointer.texcoordY = 1.0 - posY / canvas.height;
      pointer.deltaX = correctDeltaX(pointer.texcoordX - pointer.prevTexcoordX);
      pointer.deltaY = correctDeltaY(pointer.texcoordY - pointer.prevTexcoordY);
      pointer.moved = Math.abs(pointer.deltaX) > 0 || Math.abs(pointer.deltaY) > 0;
      pointer.color = color;
    }

    /** Smoothly interpolate pointer position each frame and generate splats */
    function updateSmoothedPointer() {
      if (!smoothPointer.active) return;
      const prevX = smoothPointer.x;
      const prevY = smoothPointer.y;
      smoothPointer.x += (smoothPointer.targetX - smoothPointer.x) * SMOOTH_FACTOR;
      smoothPointer.y += (smoothPointer.targetY - smoothPointer.y) * SMOOTH_FACTOR;

      const pointer = pointers[0];
      const texX = smoothPointer.x / canvas.width;
      const texY = 1.0 - smoothPointer.y / canvas.height;
      const dx = correctDeltaX(texX - (prevX / canvas.width));
      const dy = correctDeltaY(texY - (1.0 - prevY / canvas.height));

      // Splat when moving; gentle ambient pulse when still
      const len = Math.sqrt(dx * dx + dy * dy);
      if (len > 0.00005) {
        splat(texX, texY, dx * config.SPLAT_FORCE, dy * config.SPLAT_FORCE, pointer.color);
      } else {
        // Ambient pulse ΓÇö gently expand the revealed area while hovering
        const jx = (Math.random() - 0.5) * 0.0003;
        const jy = (Math.random() - 0.5) * 0.0003;
        splat(texX, texY, jx * config.SPLAT_FORCE * 0.15, jy * config.SPLAT_FORCE * 0.15, pointer.color);
      }
    }

    // ΓöÇΓöÇ Resize ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    function resizeCanvas() {
      const width = scaleByPixelRatio(canvas.clientWidth);
      const height = scaleByPixelRatio(canvas.clientHeight);
      if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width;
        canvas.height = height;
        return true;
      }
      return false;
    }

    // ΓöÇΓöÇ Main loop ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    function calcDeltaTime() {
      const now = Date.now();
      let dt = (now - lastUpdateTime) / 1000;
      dt = Math.min(dt, 0.016666);
      lastUpdateTime = now;
      return dt;
    }

    function updateColors(dt: number) {
      colorUpdateTimer += dt * config.COLOR_UPDATE_SPEED;
      if (colorUpdateTimer >= 1) {
        colorUpdateTimer = wrap(colorUpdateTimer, 0, 1);
        pointers.forEach((p: any) => { p.color = generateColor(); });
      }
    }

    function applyInputs() {
      pointers.forEach((p: any) => {
        if (p.moved) {
          p.moved = false;
          splatPointer(p);
        }
      });
    }

    function updateFrame() {
      if (!isActive) return;
      const dt = calcDeltaTime();
      if (resizeCanvas()) initFramebuffers();
      updateColors(dt);
      updateSmoothedPointer();
      applyInputs();
      step(dt);
      render(null);
      animationFrameId.current = requestAnimationFrame(updateFrame);
    }

    // ΓöÇΓöÇ Event handlers (scoped to container) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    let firstMove = false;
    function handleMouseMove(e: MouseEvent) {
      const rect = container.getBoundingClientRect();
      const posX = scaleByPixelRatio(e.clientX - rect.left);
      const posY = scaleByPixelRatio(e.clientY - rect.top);
      const pointer = pointers[0];

      // Feed raw position to the smooth interpolator
      smoothPointer.targetX = posX;
      smoothPointer.targetY = posY;
      smoothPointer.active = true;

      if (!firstMove) {
        pointer.color = generateColor();
        // Snap smooth position on first entry to avoid lerp from (0,0)
        smoothPointer.x = posX;
        smoothPointer.y = posY;
        updatePointerMoveData(pointer, posX, posY, pointer.color);
        firstMove = true;
      } else {
        updatePointerMoveData(pointer, posX, posY, pointer.color);
      }
    }

    function handleMouseEnter(e: MouseEvent) {
      const rect = container.getBoundingClientRect();
      const posX = scaleByPixelRatio(e.clientX - rect.left);
      const posY = scaleByPixelRatio(e.clientY - rect.top);
      smoothPointer.x = posX;
      smoothPointer.y = posY;
      smoothPointer.targetX = posX;
      smoothPointer.targetY = posY;
      smoothPointer.active = true;
      pointers[0].color = generateColor();
    }

    function handleMouseLeave() {
      smoothPointer.active = false;
    }

    function handleTouchMove(e: TouchEvent) {
      const rect = container.getBoundingClientRect();
      const touches = e.targetTouches;
      const pointer = pointers[0];
      for (let i = 0; i < touches.length; i++) {
        const posX = scaleByPixelRatio(touches[i].clientX - rect.left);
        const posY = scaleByPixelRatio(touches[i].clientY - rect.top);
        updatePointerMoveData(pointer, posX, posY, pointer.color);
      }
    }

    function handleTouchStart(e: TouchEvent) {
      const rect = container.getBoundingClientRect();
      const touches = e.targetTouches;
      const pointer = pointers[0];
      for (let i = 0; i < touches.length; i++) {
        const posX = scaleByPixelRatio(touches[i].clientX - rect.left);
        const posY = scaleByPixelRatio(touches[i].clientY - rect.top);
        pointer.id = touches[i].identifier;
        pointer.down = true;
        pointer.moved = false;
        pointer.texcoordX = posX / canvas.width;
        pointer.texcoordY = 1.0 - posY / canvas.height;
        pointer.prevTexcoordX = pointer.texcoordX;
        pointer.prevTexcoordY = pointer.texcoordY;
        pointer.deltaX = 0;
        pointer.deltaY = 0;
        pointer.color = generateColor();
      }
    }

    // Bind events to CONTAINER (not window) for scoped interactions
    container.addEventListener('mousemove', handleMouseMove);
    container.addEventListener('mouseenter', handleMouseEnter);
    container.addEventListener('mouseleave', handleMouseLeave);
    container.addEventListener('touchstart', handleTouchStart, { passive: true });
    container.addEventListener('touchmove', handleTouchMove, { passive: true });

    updateFrame();

    return () => {
      isActive = false;
      if (animationFrameId.current) {
        cancelAnimationFrame(animationFrameId.current);
        animationFrameId.current = null;
      }
      container.removeEventListener('mousemove', handleMouseMove);
      container.removeEventListener('mouseenter', handleMouseEnter);
      container.removeEventListener('mouseleave', handleMouseLeave);
      container.removeEventListener('touchstart', handleTouchStart);
      container.removeEventListener('touchmove', handleTouchMove);
    };
  }, [containerRef]);

  return (
    <canvas
      ref={canvasRef}
      className={className}
      style={{
        width: '100%',
        height: '100%',
        display: 'block',
        ...style,
      }}
    />
  );
}

/**
 * FluidMaskCursor ΓÇö WebGL Navier-Stokes fluid simulation for hover-reveal masking.
 *
 * Renders on a hidden 48x48 canvas and exports an inverted luminance mask
 * via toDataURL at ~24fps. Parent applies this as CSS mask-image on a cover
 * layer: white = layer visible, black = layer erased (reveals content beneath).
 *
 * The fluid sim produces organic, deforming edges with inertia ΓÇö the mask
 * follows the cursor with weighted trailing pointers for smooth, delayed motion.
 */

import { useEffect, useRef, memo } from 'react';

interface FluidMaskCursorProps {
  onMaskFrame?: (dataUrl: string) => void;
  paused?: boolean;
}

/* ΓöÇΓöÇΓöÇ Fluid config ΓÇö EXTREME PERFORMANCE (Low CPU Load) ΓöÇΓöÇΓöÇ */
const MASK_RES = 48;
const SIM_RESOLUTION = 64;
const DYE_RESOLUTION = 128;
const DENSITY_DISSIPATION = 3.5;
const VELOCITY_DISSIPATION = 0.98;
const PRESSURE = 0.1;
const PRESSURE_ITERATIONS = 12;
const CURL = 10;
const SPLAT_RADIUS = 0.16;
const SPLAT_FORCE = 10000;
const SHADING = true;

function FluidMaskCursor({ onMaskFrame, paused = false }: FluidMaskCursorProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const rafRef = useRef<number | null>(null);
  const pausedRef = useRef(paused);
  const onMaskFrameRef = useRef(onMaskFrame);

  useEffect(() => {
    pausedRef.current = paused;
  }, [paused]);

  useEffect(() => {
    onMaskFrameRef.current = onMaskFrame;
  }, [onMaskFrame]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    let alive = true;
    let pageHidden = document.hidden;

    // Low resolution is key for mask performance
    canvas.width = MASK_RES;
    canvas.height = MASK_RES;

    const handleVisibilityChange = () => { pageHidden = document.hidden; };
    document.addEventListener('visibilitychange', handleVisibilityChange);

    let lastUpdateTime = Date.now();
    let _maskCursorDirty = false;
    const pointers = [
      { x: 0, y: 0, px: 0, py: 0, mass: 0.18 },
      { x: 0, y: 0, px: 0, py: 0, mass: 0.10 },
    ];
    let mouseX = 0, mouseY = 0;
    let initialized = false;

    // Use WebGL2 for better performance if available
    const params: WebGLContextAttributes = {
      alpha: true,
      depth: false,
      stencil: false,
      antialias: false,
      preserveDrawingBuffer: false, // Set to false for better perf
    };

    let gl = canvas.getContext('webgl2', params) as WebGL2RenderingContext | null;
    const isWebGL2 = !!gl;
    if (!gl) gl = (canvas.getContext('webgl', params) || canvas.getContext('experimental-webgl', params)) as WebGL2RenderingContext | null;
    if (!gl) return;

    let contextLost = false;
    const onLost = (e: Event) => { e.preventDefault(); contextLost = true; };
    canvas.addEventListener('webglcontextlost', onLost);

    let halfFloat: any;
    let supportLinearFiltering: any;
    if (isWebGL2) {
      gl.getExtension('EXT_color_buffer_float');
      supportLinearFiltering = gl.getExtension('OES_texture_float_linear');
    } else {
      halfFloat = gl.getExtension('OES_texture_half_float');
      supportLinearFiltering = gl.getExtension('OES_texture_half_float_linear');
    }

    gl.clearColor(0.0, 0.0, 0.0, 0.0);
    const halfFloatTexType = isWebGL2 ? (gl as any).HALF_FLOAT : halfFloat && halfFloat.HALF_FLOAT_OES;

    // ... (rest of the WebGL glue code remains similar but we optimize the loop)

    function getSupportedFormat(gl: WebGL2RenderingContext, intFmt: number, fmt: number, type: number): any {
      if (!supportRenderTextureFormat(gl, intFmt, fmt, type)) {
        switch (intFmt) {
          case (gl as any).R16F: return getSupportedFormat(gl, (gl as any).RG16F, (gl as any).RG, type);
          case (gl as any).RG16F: return getSupportedFormat(gl, (gl as any).RGBA16F, (gl as any).RGBA, type);
          default: return null;
        }
      }
      return { internalFormat: intFmt, format: fmt };
    }

    function supportRenderTextureFormat(gl: WebGL2RenderingContext, intFmt: number, fmt: number, type: number) {
      const tex = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, tex);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
      gl.texImage2D(gl.TEXTURE_2D, 0, intFmt, 4, 4, 0, fmt, type, null);
      const fbo = gl.createFramebuffer();
      gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
      gl.framebufferTexture2D(gl.FRAMEBUFFER, (gl as any).COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
      const ok = gl.checkFramebufferStatus(gl.FRAMEBUFFER) === gl.FRAMEBUFFER_COMPLETE;
      gl.deleteTexture(tex); gl.deleteFramebuffer(fbo); gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      return ok;
    }

    const formatRGBA = isWebGL2 ? getSupportedFormat(gl, (gl as any).RGBA16F, (gl as any).RGBA, halfFloatTexType) : getSupportedFormat(gl, (gl as any).RGBA, (gl as any).RGBA, halfFloatTexType);
    const formatRG = isWebGL2 ? getSupportedFormat(gl, (gl as any).RG16F, (gl as any).RG, halfFloatTexType) : getSupportedFormat(gl, (gl as any).RGBA, (gl as any).RGBA, halfFloatTexType);
