  useEffect(() => {
    if (hydrationRef.current) return;
    hydrationRef.current = true;

    const hasStoredUser = !!sessionManager.getUser();

    if (!hasStoredUser) {
      // No existing session ΓÇö set hydrated
      setState({ ...INITIAL_STATE, isHydrated: true });
      return;
    }

