        user,
        isAuthenticated: true,
        isLoading: false,
        isHydrated: true,
        trust,
        restriction,
      });
    } catch (err) {
      setState((prev) => ({ ...prev, isLoading: false }));
      throw err;
    }
  }, []);

  const signup = useCallback(async (fullName: string, email: string, password: string) => {
    setState((prev) => ({ ...prev, isLoading: true }));

