    clearCsrfToken();
    clearMonitoringUser();
    pendingPasswordRef.current = null;
    clearPending();
    setState({ ...INITIAL_STATE, isHydrated: true });
  }, []);

  const googleSignIn = useCallback(async (credential: string) => {
    setState((prev) => ({ ...prev, isLoading: true }));

    try {
      const response = await api.post<{
        user: User;
        accessToken: string;
        csrfToken?: string;
        isNewUser?: boolean;
