        user,
        isAuthenticated: true,
        isLoading: false,
        isHydrated: true,
        trust,
        restriction,
      });
    } catch (err) {
      setState((prev) => ({ ...prev, isLoading: false }));
      throw err;
    }
  }, []);

  const contextValue = useMemo<AuthContextType>(
    () => ({ ...state, login, signup, verifyOtp, googleSignIn, logout }),
    [state, login, signup, verifyOtp, googleSignIn, logout],
  );

